// Documentations of the build: OnPrem versions built, Cloud and Log
// Management if built.
export function targetsOf({ versions, cloud, logmanagement }) {
  return TARGETS.filter((target) => {
    if (target.docs === 'cloud') return cloud;
    if (target.docs === 'logmanagement') return logmanagement;
    return versions.includes(target.version);
  });
}

// Entries of docusaurus-plugin-openapi-docs: one per documentation and API.
export function openapiConfig(targets) {
  return Object.fromEntries(
    targets.flatMap((target) =>
      target.apis.map(({ api, dir, spec }) => [
        `${target.version.replace('.', '')}-${dir}`,
        {
          specPath: `openapi/${spec}`,
          outputDir: `${target.docs}/${REFERENCE_DIR}/${dir}`,
          sidebarOptions: { groupPathsBy: 'tag' },
        },
      ]),
    ),
  );
}

// Sidebar items of an API reference: sidebar.json, written by generate.mjs
// next to the pages. When the pages are not generated (API=0), a link to the
// former reference on docs-api.centreon.com instead, so that the sidebar is
// still valid.
const FALLBACK_URLS = {
  web: 'https://docs-api.centreon.com/api/centreon-web/',
  map: 'https://docs-api.centreon.com/api/centreon-map/',
  bam: 'https://docs-api.centreon.com/api/centreon-bam/',
  autodiscovery: 'https://docs-api.centreon.com/api/centreon-autodiscovery/',
  'log-management': 'https://docs-api.centreon.com/api/centreon-log-management/',
};

export async function apiSidebarItemsGenerator({ defaultSidebarItemsGenerator, ...args }) {
  const { item, version } = args;
  if (!item.dirName.startsWith(`${REFERENCE_DIR}/`)) {
    return defaultSidebarItemsGenerator(args);
  }
  const file = path.join(version.contentPath, item.dirName, 'sidebar.json');
  if (fs.existsSync(file)) {
    return JSON.parse(fs.readFileSync(file, 'utf8'));
  }
  const dir = path.basename(item.dirName);
  return [{ type: 'link', label: 'API reference', href: FALLBACK_URLS[dir] ?? 'https://docs-api.centreon.com/' }];
}
